SELECT ?county1 ?county1Label ?county2 ?county2Label WHERE {
  # Subquery to get all English, Welsh, and Scottish counties
  {
    SELECT ?county WHERE {
      { ?county wdt:P31 wd:Q180673. } # English county
      UNION
      { ?county wdt:P31 wd:Q180674. } # Welsh county
      UNION
      { ?county wdt:P31 wd:Q180675. } # Scottish county
    }
  }
  # Find pairs that share a border
  ?county1 wdt:P47 ?county2.
  # Ensure both are counties from the subquery
  ?county1 wdt:P31 ?type1.
  ?county2 wdt:P31 ?type2.
  FILTER(?type1 IN (wd:Q180673, wd:Q180674, wd:Q180675))
  FILTER(?type2 IN (wd:Q180673, wd:Q180674, wd:Q180675))
  # Avoid duplicate pairs (A-B and B-A)
  FILTER(STR(?county1) < STR(?county2))
  SERVICE wikibase:label { bd:serviceParam wikibase:language "en". }
}

