SELECT DISTINCT ?country ?countryLabel WHERE {
  # Top 3 traditional universities in Ghana by number of items
  SELECT ?university WHERE {
    ?university wdt:P31 wd:Q3918;          # instance of university
                wdt:P17 wd:Q117.           # country = Ghana
  }
  ORDER BY DESC(?count)
  LIMIT 3
  # Note: This subquery is conceptual; actual ranking may require additional data.
  # For simplicity, we select all Ghanaian universities and then limit.

  # Alternative: Use known top universities
  VALUES ?university {
    wd:Q1049051  # University of Ghana
    wd:Q1513889  # Kwame Nkrumah University of Science and Technology
    wd:Q7895337  # University of Cape Coast
  }

  # People affiliated with these universities
  ?person wdt:P69 ?university.             # educated at
  OPTIONAL { ?person wdt:P1416 ?affiliation } # affiliation (if needed)

  # Country of origin
  ?person wdt:P27 ?country.                # country of citizenship
  SERVICE wikibase:label { bd:serviceParam wikibase:language "en". }
}

