SELECT ?item ?itemLabel ?coord ?type WHERE {
  {
    ?item wdt:P31 wd:Q23397 ;   # instance of lake
          wdt:P17 wd:Q142 ;     # country France
          wdt:P625 ?coord .     # coordinate location
    BIND("Lake" AS ?type)
  }
  UNION
  {
    ?item wdt:P31 wd:Q4022 ;   # instance of river
          wdt:P17 wd:Q142 ;     
          wdt:P625 ?coord .
    BIND("River" AS ?type)
  }
  SERVICE wikibase:label { bd:serviceParam wikibase:language "en". }
}

