  ?law wdt:P1001 wd:Q252.                   # Applies to jurisdiction: Indonesia
  ?law wdt:P1269 ?aspect.                   # Facet of / applies to aspect
  ?aspect wdt:P31 wd:Q103817.               # Instance of indigenous people
