SELECT ?decade (COUNT(?item) AS ?count) ?item ?itemLabel WHERE {
  ?item wdt:P195 wd:Q4945142. # Boyer collection
  ?item wdt:P577 ?publicationDate. # publication date
  BIND(YEAR(?publicationDate) AS ?year)
  BIND(CONCAT(
    STR(FLOOR(?year / 10) * 10),
    "s"
  ) AS ?decade)
  SERVICE wikibase:label { bd:serviceParam wikibase:language "en". }
}
GROUP BY ?decade ?item ?itemLabel
ORDER BY ?decade ?itemLabel

