PREFIX wikibase: <http://wikiba.se/ontology#>
PREFIX bd: <http://www.bigdata.com/rdf#>

SELECT ?director ?directorLabel ?filmCount ?sitelinkCount WHERE {
  {
    SELECT ?director (COUNT(DISTINCT ?film) AS ?filmCount) WHERE {
      ?film wdt:P57 ?director .
      ?director wdt:P106 wd:Q2526255 .
    }
    GROUP BY ?director
  }
  {
    SELECT ?director (COUNT(DISTINCT ?sitelink) AS ?sitelinkCount) WHERE {
      ?director wikibase:sitelink ?sitelink .
      ?director wdt:P106 wd:Q2526255 .
    }
    GROUP BY ?director
  }
  SERVICE wikibase:label { bd:serviceParam wikibase:language "en". }
}
ORDER BY DESC(?filmCount) DESC(?sitelinkCount)
LIMIT 100

SELECT ?countryLabel ?cases WHERE {
  ?country wdt:P31 wd:Q3624078;          # instance of sovereign state
            p:P1603 ?caseStmt.
  ?caseStmt ps:P1603 ?cases;             # number of cases
            pq:P642 wd:Q84263196.        # applies to COVID-19 pandemic
  SERVICE wikibase:label { bd:serviceParam wikibase:language "en". }
}
ORDER BY DESC(?cases)

SELECT ?thesis ?thesisLabel ?author ?authorLabel ?institution ?institutionLabel WHERE {
  ?thesis wdt:P31 wd:Q187685.               # doctoral thesis
  ?thesis wdt:P50 ?author.                  # author
  ?thesis wdt:P1026 ?institution.           # awarding institution
  SERVICE wikibase:label { bd:serviceParam wikibase:language "[AUTO_LANGUAGE],en". }
}

SELECT ?parentTaxon ?parentTaxonLabel WHERE {
  wd:Q2868861 wdt:P171 ?parentTaxon .
  SERVICE wikibase:label { bd:serviceParam wikibase:language "en". }
}

SELECT ?pubmedId WHERE {
  wd:Q30255710 wdt:P698 ?pubmedId .
}

SELECT ?instrument ?instrumentLabel WHERE {
  ?instrument wdt:P170 wd:Q182414 .
  ?instrument wdt:P31/wdt:P279* wd:Q329809 .
  SERVICE wikibase:label { bd:serviceParam wikibase:language "en". }
}

SELECT ?article WHERE {
  ?article wdt:P31 wd:Q13442814 ;   # instance of scholarly article
           wdt:P1476 ?title .       # has title
  FILTER(CONTAINS(LCASE(?title), "zika"))
}

SELECT ?item WHERE {
  ?item schema:description ?description .
  FILTER(LANG(?description) = "en")
  FILTER NOT EXISTS {
    ?item rdfs:label ?label .
    FILTER(LANG(?label) = "en")
  }
}

SELECT ?ingredient ?ingredientLabel WHERE {
  wd:Q28803 wdt:P527 ?ingredient .  # sandwich has parts (ingredients)
  FILTER(?ingredient != wd:Q7802)   # exclude bread (Q7802)
  SERVICE wikibase:label { bd:serviceParam wikibase:language "en". }
}

SELECT ?episode ?episodeLabel ?season ?episodeNumber WHERE {
  ?episode wdt:P31 wd:Q21191270;   # Instance of television series episode
           wdt:P179 wd:Q1228;      # Part of series: Law & Order
           wdt:P920 ?season;       # Season number
           wdt:P1545 ?episodeNumber.  # Episode number within season
  SERVICE wikibase:label { bd:serviceParam wikibase:language "en". }
}

SELECT ?professionLabel (AVG(?lifespan) AS ?averageLifespan) WHERE {
  ?person wdt:P31 wd:Q5.
  ?person wdt:P106 ?profession.
  ?person wdt:P569 ?birthDate.
  ?person wdt:P570 ?deathDate.
  BIND(?deathDate - ?birthDate AS ?lifespan)
  SERVICE wikibase:label { bd:serviceParam wikibase:language "en". }
}
GROUP BY ?professionLabel

SELECT ?property ?value WHERE {
  wd:Q134772 ?property ?value .
  FILTER NOT EXISTS { wd:Q164047 ?property ?value }
}

SELECT ?artist ?artistLabel (GROUP_CONCAT(DISTINCT ?occupationLabel; SEPARATOR=", ") AS ?occupations) (SAMPLE(?image) AS ?image) WHERE {
  VALUES ?trans { wd:Q189125 wd:Q1052281 wd:Q2449503 wd:Q48270 }
  ?artist wdt:P31 wd:Q5 .
  ?artist wdt:P21 ?trans .
  ?artist wdt:P106 ?occupation .
  ?occupation wdt:P279* wd:Q483501 .
  ?artist wdt:P18 ?image .
  SERVICE wikibase:label { bd:serviceParam wikibase:language "en". }
}
GROUP BY ?artist ?artistLabel
ORDER BY ?artistLabel

SELECT ?place ?placeLabel WHERE {
  wd:Q1474962 wdt:P625 ?papaStourCoords.
  ?place wdt:P625 ?coords.
  FILTER(geof:distance(?papaStourCoords, ?coords) < 50)
  SERVICE wikibase:label { bd:serviceParam wikibase:language "en". }
}

SELECT ?item ?itemLabel ?publicationDate ?place ?placeLabel WHERE {
  ?item wdt:P31 wd:Q11032.  # instance of (P31) = journal (Q11032)
  UNION
  ?item wdt:P31 wd:Q11033.  # instance of (P31) = newspaper (Q11033)
  ?item wdt:P17 wd:Q25.     # country (P17) = Wales (Q25)
  OPTIONAL { ?item wdt:P577 ?publicationDate . }  # publication date (P577)
  OPTIONAL { ?item wdt:P291 ?place . }            # place of publication (P291)
  SERVICE wikibase:label { bd:serviceParam wikibase:language "en". }
}

SELECT ?economist ?economistLabel ?fieldOfWork ?fieldOfWorkLabel ?nationality ?nationalityLabel WHERE {
  ?economist wdt:P106 wd:Q188094.  # instance of economist
  OPTIONAL { ?economist wdt:P101 ?fieldOfWork. }  # field of work
  OPTIONAL { ?economist wdt:P27 ?nationality. }   # country of citizenship
  SERVICE wikibase:label { bd:serviceParam wikibase:language "en". }
}
ORDER BY ?economistLabel

SELECT ?region ?regionLabel ?populationDensity WHERE {
  ?region wdt:P31 wd:Q82794.        # Instance of European region
  ?region wdt:P1082 ?population.    # Population
  ?region wdt:P2046 ?area.          # Area in square kilometers
  BIND(?population / ?area AS ?populationDensity)
  FILTER(?populationDensity < 30)
  SERVICE wikibase:label { bd:serviceParam wikibase:language "en". }
}

SELECT ?restaurant ?restaurantLabel ?stars WHERE {
  ?restaurant wdt:P31 wd:Q11707 ;          # instance of restaurant
              wdt:P17 wd:Q32 ;             # located in Luxembourg
              wdt:P1149 ?stars .           # has Michelin star rating
  SERVICE wikibase:label { bd:serviceParam wikibase:language "en". }
}

SELECT ?property ?propertyLabel (COUNT(?property) AS ?count) WHERE {
  ?statement a wikibase:Statement .
  ?statement prov:wasDerivedFrom ?reference .
  ?reference ?property ?value .
  FILTER(?property != rdf:type)
  SERVICE wikibase:label { bd:serviceParam wikibase:language "en". }
}
GROUP BY ?property ?propertyLabel
ORDER BY DESC(?count)
LIMIT 20

SELECT ?project ?projectLabel WHERE {
  ?project wdt:P31 wd:Q16663377. # Instance of WikiProject
  ?project wdt:P921 wd:Q467.      # Main subject is women
  SERVICE wikibase:label { bd:serviceParam wikibase:language "en". }
}

SELECT ?theatre ?theatreLabel ?exteriorImage ?interiorImage WHERE {
  ?theatre wdt:P31/wdt:P279* wd:Q243983 . # theatre or subclass
  ?theatre wdt:P131 ?location .
  ?location rdfs:label "Carthalia"@en .
  OPTIONAL { ?theatre wdt:P18 ?exteriorImage . }
  OPT

SELECT ?country ?countryLabel (COUNT(?person) AS ?count) WHERE {
  ?person wdt:P31 wd:Q5.                # instance of human
  ?person wdt:P27 ?country.             # country of citizenship
  ?person wdt:P1853 ?bloodType.         # blood type
  # Optionally filter for a specific blood type, e.g., wd:Q2013 for A+
  # FILTER(?bloodType = wd:Q2013)
  SERVICE wikibase:label { bd:serviceParam wikibase:language "en". }
}
GROUP BY ?country ?countryLabel
ORDER BY DESC(?count)

SELECT ?artwork ?artworkLabel WHERE {
  ?artwork wdt:P31 wd:Q3305213.  # Instance of painting (or artwork)
  ?artwork wdt:P195 wd:Q636400.  # Collection: Ashmolean Museum
  ?artwork wdt:P195 wd:Q657415.  # Collection: Cleveland Museum of Art
  SERVICE wikibase:label { bd:serviceParam wikibase:language "en". }
}

SELECT ?movie ?movieLabel ?sitelinks WHERE {
  ?movie wdt:P31 wd:Q11424.          # instance of film
  ?movie wdt:P161 wd:Q106584.        # cast member: Jean-Paul Belmondo (Q106584)
  ?movie wikibase:sitelinks ?sitelinks.
  SERVICE wikibase:label { bd:serviceParam wikibase:language "en". }
}
ORDER BY DESC(?sitelinks)

SELECT ?church ?churchLabel ?dedicatedToLabel WHERE {
  ?church wdt:P31 wd:Q16970.          # instance of church
  ?church wdt:P17 wd:Q213.            # country: Czech Republic
  ?church wdt:P825 ?dedicatedTo.      # dedicated to
  VALUES ?dedicatedTo { wd:Q153183 wd:Q152390 }  # St. Wenceslas or St. Cyril and Methodius
  SERVICE wikibase:label { bd:serviceParam wikibase:language "en". }
}

SELECT ?item ?itemLabel ?coord WHERE {
  ?item wdt:P17 wd:Q212;
        wdt:P625 ?coord.
  SERVICE wikibase:label { bd:serviceParam wikibase:language "en". }
}

SELECT ?photographer ?photographerLabel ?birthDate WHERE {
  # Find the first photograph ever taken (View from the Window at Le Gras, 1826 or 1827)
  { SELECT (MIN(?date) AS ?firstPhotoDate) WHERE {
      wd:Q131308 wdt:P571 ?date . # View from the Window at Le Gras
    }
  }
  # Photographers born before that date
  ?photographer wdt:P106 wd:Q33231 ; # occupation: photographer
                wdt:P569 ?birthDate .
  FILTER(?birthDate < ?firstPhotoDate)
  SERVICE wikibase:label { bd:serviceParam wikibase:language "en". }
}
ORDER BY ?birthDate

SELECT ?feature ?featureLabel ?subclass ?subclassLabel WHERE {
  wd:Q105324 wdt:P279* ?feature . # Q105324 is "grammatical feature"
  OPTIONAL { ?feature wdt:P279 ?subclass . }
  SERVICE wikibase:label { bd:serviceParam wikibase:language "en". }
}

SELECT ?item ?itemLabel WHERE {
  ?item wdt:P31 wd:Q5 .                # instance of human
  ?item wdt:P21 wd:Q6581072 .          # female gender
  ?item wdt:P106 wd:Q639 .             # occupation: musician
  ?item wdt:P27 ?country .             # country of citizenship
  ?country wdt:P30 wd:Q2938 .         # located in Latin America
  ?item wdt:P1416 ?genre .            # musical genre (optional, for fame)

  # Exclude those with a Spanish Wikipedia article
  FILTER NOT EXISTS {
    ?sitelink schema:about ?item ;
              schema:isPartOf <https://es.wikipedia.org/> .
  }

  SERVICE wikibase:label { bd:serviceParam wikibase:language "en". }
}

SELECT ?statue ?statueLabel ?depictsLabel WHERE {
  ?statue wdt:P31 wd:Q179700.  # instance of statue
  ?statue wdt:P17 wd:Q145.     # country: United Kingdom
  ?statue wdt:P180 ?depicts.   # depicts
  { ?depicts wdt:P31 wd:Q5 }   # depicts a human (woman or noble)
  UNION
  { ?depicts wdt:P31 wd:Q41176 } # depicts a noble (human with noble title)
  SERVICE wikibase:label { bd:serviceParam wikibase:language "en". }
}

SELECT ?team ?teamLabel (COUNT(?player) AS ?playerCount) ?genderLabel WHERE {
  ?team wdt:P31 wd:Q89930916.  # Instance of cricket team
  OPTIONAL { ?team wdt:P527 ?player. }  # Has player
  OPTIONAL { ?team wdt:P641 ?sport. FILTER(?sport = wd:Q5375) }  # Cricket sport
  SERVICE wikibase:label { bd:serviceParam wikibase:language "en". }
  OPTIONAL { ?team wdt:P641/wdt:P31 ?gender. }  # Gender of the sport
}
GROUP BY ?team ?teamLabel ?genderLabel

SELECT DISTINCT ?entity ?entityLabel ?image WHERE {
  {
    # Works authored by Percy Bysshe Shelley
    ?entity wdt:P50 wd:Q93343.
  } UNION {
    # Spouse of Percy Bysshe Shelley
    ?entity wdt:P26 wd:Q93343.
  } UNION {
    # Children of Percy Bysshe Shelley
    ?entity wdt:P40 wd:Q93343.
  } UNION {
    # Father of Percy Bysshe Shelley
    ?entity wdt:P22 wd:Q93343.
  } UNION {
    # Mother of Percy Bysshe Shelley
    ?entity wdt:P25 wd:Q93343.
  } UNION {
    # Sibling of Percy Bysshe Shelley
    ?entity wdt:P3373 wd:Q93343.
  } UNION {
    # Notable works by Percy Bysshe Shelley (object of P800)
    wd:Q93343 wdt:P800 ?entity.
  } UNION {
    # Entities influenced by Percy Bysshe Shelley
    ?entity wdt:P737 wd:Q93343.
  }
  # Ensure the entity has an image
  ?entity wdt:P18 ?image.
  SERVICE wikibase:label { bd:serviceParam wikibase:language "en". }
}
LIMIT 100

SELECT ?film ?filmLabel ?duration ?releaseDate WHERE {
  ?film wdt:P31 wd:Q11424.   # instance of film
  ?film wdt:P495 wd:Q39.     # country of origin: Switzerland
  OPTIONAL { ?film wdt:P2047 ?duration. }   # duration in minutes
  OPTIONAL { ?film wdt:P577 ?releaseDate. } # publication date
  SERVICE wikibase:label { bd:serviceParam wikibase:language "en". }
}

SELECT ?member ?memberLabel ?birthDate WHERE {
  ?member wdt:P463 wd:Q188304.   # member of Illuminati Order
  ?member wdt:P569 ?birthDate.   # birth date
  SERVICE wikibase:label { bd:serviceParam wikibase:language "en". }
}
ORDER BY ?memberLabel

SELECT ?collection ?size WHERE {
  ?collection wdt:P31 wd:Q2073 . # instance of art collection
  ?collection wdt:P17 wd:Q213 . # country Czech Republic
  OPTIONAL { ?collection wdt:P2046 ?size . } # area/size
}

SELECT ?airport ?airportLabel ?poetLabel WHERE {
  ?airport wdt:P31/wdt:P279* wd:Q1248784.  # airport or subclass thereof
  ?airport wdt:P138 ?poet.                # named after something
  ?poet wdt:P106 wd:Q49757.               # that something is a poet
  SERVICE wikibase:label { bd:serviceParam wikibase:language "en". }
}

SELECT ?city ?cityLabel ?schoolCount ?location WHERE {
  {
    SELECT ?city (COUNT(?school) AS ?schoolCount) (SAMPLE(?location) AS ?location) WHERE {
      ?city wdt:P31 wd:Q747074;  # Italian city
            wdt:P17 wd:Q38;      # country Italy
            wdt:P625 ?location.  # coordinate location
      ?school wdt:P31 wd:Q3914;  # school
               wdt:P131 ?city.   # located in the administrative territorial entity
    }
    GROUP BY ?city
    HAVING (?schoolCount > 0)
  }
  SERVICE wikibase:label { bd:serviceParam wikibase:language "en". }
}
ORDER BY DESC(?schoolCount)

SELECT ?item ?itemLabel ?coord WHERE {
  ?item wdt:P31 wd:Q1050998;   # instance of hillfort
        wdt:P17 wd:Q145;       # country United Kingdom
        wdt:P625 ?coord.       # coordinate location
  FILTER NOT EXISTS { ?item wdt:P18 ?image. }  # no image
  SERVICE wikibase:label { bd:serviceParam wikibase:language "en". }
}

SELECT ?pathway ?geneCount ?metaboliteCount WHERE {
  {
    SELECT ?pathway (COUNT(DISTINCT ?gene) AS ?geneCount) WHERE {
      ?pathway wdt:P31 wd:Q4915012.  # instance of biological pathway
      OPTIONAL { ?pathway wdt:P527 ?gene . }  # has part gene
    }
    GROUP BY ?pathway
  }
  {
    SELECT ?pathway (COUNT(DISTINCT ?metabolite) AS ?metaboliteCount) WHERE {
      ?pathway wdt:P31 wd:Q4915012.
      OPTIONAL { ?pathway wdt:P527 ?metabolite . }  # has part metabolite
    }
    GROUP BY ?pathway
  }
}

SELECT DISTINCT ?author ?authorLabel WHERE {
  ?work wdt:P50 ?author .
  ?work wdt:P577 ?publicationDate .
  ?work wdt:P953 ?fullWorkAvailableOnline .
  FILTER(YEAR(?publicationDate) >= 1500 && YEAR(?publicationDate) <= 1800)
  SERVICE wikibase:label { bd:serviceParam wikibase:language "en". }
}

SELECT DISTINCT ?type ?typeLabel WHERE {
  ?item wdt:P2003 ?instagram.
  ?item wdt:P31 ?type.
  SERVICE wikibase:label { bd:serviceParam wikibase:language "en". }
}

PREFIX wd: <http://www.wikidata.org/entity/>
PREFIX wdt: <http://www.wikidata.org/prop/direct/>
PREFIX wikibase: <http://wikiba.se/ontology#>
PREFIX bd: <http://www.bigdata.com/rdf#>

SELECT DISTINCT ?org ?orgLabel
WHERE {
  ?org wdt:P112 ?founder .
  ?founder wdt:P69 wd:Q34433 .
  SERVICE wikibase:label { bd:serviceParam wikibase:language "[AUTO_LANGUAGE],en". }
}

SELECT DISTINCT ?person ?personLabel WHERE {
  ?person wdt:P31 wd:Q5.                # Instance of human
  ?person wdt:P106 wd:Q82955.            # Occupation: politician
  { ?person wdt:P2037 ?github. }         # GitHub username
  UNION
  { ?person wdt:P4107 ?cpan. }          # CPAN username
  UNION
  { ?person wdt:P4174 ?wm. }            # Wikimedia username
  SERVICE wikibase:label { bd:serviceParam wikibase:language "en". }
}

SELECT ?country ?countryLabel (COUNT(DISTINCT ?color) AS ?colorCount) WHERE {
  ?country wdt:P31 wd:Q3624078 ;   # sovereign state
           wdt:P163 ?flag .        # flag item
  ?flag wdt:P462 ?color .          # color used in flag
  SERVICE wikibase:label { bd:serviceParam wikibase:language "en". }
}
GROUP BY ?country ?countryLabel
ORDER BY DESC(?colorCount)
LIMIT 10

SELECT ?story ?storyLabel ?location ?locationLabel ?coord WHERE {
  ?story wdt:P31 wd:Q222749.   # instance of travel blog
  ?story wdt:P407 wd:Q150.     # language French
  OPTIONAL {
    ?story wdt:P276 ?location . # location mentioned
    ?location wdt:P625 ?coord . # coordinates of location
  }
  SERVICE wikibase:label

SELECT ?item ?itemLabel WHERE {
  ?item wdt:P31 wd:Q179700. # statue or monument
  ?item wdt:P547 ?subject. # dedicated to
  ?subject wdt:P106 ?occupation. # occupation
  { ?subject wdt:P106 wd:Q127824 } # slave owner
  UNION
  { ?subject wdt:P106 wd:Q129801 } # slave trader
  SERVICE wikibase:label { bd:serviceParam wikbase:language "en". }
}

SELECT ?townHall ?townHallLabel WHERE {
  ?commune wdt:P47 wd:Q90.          # communes that share a border with Paris
  ?townHall wdt:P31 wd:Q543654;     # instance of town hall (hôtel de ville)
             wdt:P131 ?commune.     # located in that commune
  SERVICE wikibase:label { bd:serviceParam wikibase:language "en". }
}

PREFIX wdt: <http://www.wikidata.org/prop/direct/>
PREFIX rdfs: <http://www.w3.org/2000/01/rdf-schema#>

SELECT ?item ?itemLabel ?coord WHERE {
  ?item wdt:P625 ?coord .
  ?item rdfs:label "Ordnance Survey Old Series preparatory drawings"@en .
  SERVICE wikibase:label { bd:serviceParam wikibase:language "en". }
}

SELECT ?leader ?leaderLabel ?party ?partyLabel ?alignment ?alignmentLabel WHERE {
  ?leader wdt:P31 wd:Q5.                # instance of human
  ?leader wdt:P39 wd:Q11696.            # position held: head of state (or use wd:Q2285706 for head of government)
  ?leader wdt:P102 ?party.              # member of political party
  OPTIONAL { ?party wdt:P1552 ?alignment. }  # has alignment (e.g., left-wing, right-wing)
  SERVICE wikibase:label { bd:serviceParam wikibase:language "en". }
}
LIMIT 100

SELECT ?person ?personLabel (COUNT(?letter) AS ?letterCount) WHERE {
  ?person wdt:P31 wd:Q5 .
  ?letter wdt:P1416 ?person .
  SERVICE wikibase:label { bd:serviceParam wikibase:language "en". }
}
GROUP BY ?person ?personLabel
ORDER BY DESC(?letterCount)
LIMIT 100

SELECT ?article WHERE {
  ?person wdt:P31 wd:Q5.  # Instance of human
  ?article schema:about ?person ;
           schema:isPartOf <https://en.wikipedia.org/> .
  FILTER NOT EXISTS { ?person wdt:P18 ?image . }
}

SELECT ?character ?characterLabel WHERE {
  ?character wdt:P31/wdt:P279* wd:Q21638430.
  SERVICE wikibase:label { bd:serviceParam wikibase:language "en". }
}

SELECT ?facility ?facilityLabel ?type ?typeLabel ?location WHERE {
  # Kalimpong district (Q1684287)
  wd:Q1684287 wdt:P31 wd:Q188509.  # instance of district of India
  ?facility wdt:P131 wd:Q1684287.  # located in Kalimpong district
  ?facility wdt:P31/wdt:P279* wd:Q159334.  # medical facility (or subclass)
  ?facility wdt:P625 ?location.         # coordinate location
  OPTIONAL { ?facility wdt:P31 ?type. } # type of facility
  SERVICE wikibase:label { 
    bd:serviceParam wikibase:language "en". 
    ?facility rdfs:label ?facilityLabel.
    ?type rdfs:label ?typeLabel.
  }
}

SELECT ?canal ?canalLabel ?location WHERE {
  SERVICE wikibase:around {
    wd:Q4093 wdt:P625 ?location.
    bd:serviceParam wikibase:radius "800".
    bd:serviceParam wikibase:distance ?distance.
  }
  ?canal wdt:P31/wdt:P279* wd:Q12284;
         wdt:P625 ?canalLocation.
  FILTER(?distance <= 800)
  SERVICE wikibase:label { bd:serviceParam wikibase:language "en". }
}

SELECT ?hillfort ?hillfortLabel ?atlasId ?wikipedia WHERE {
  ?hillfort wdt:P31 wd:Q105099.
  ?hillfort wdt:P4014 ?atlasId.
  ?wikipedia schema:about ?hillfort;
             schema:isPartOf <https://en.wikipedia.org/>.
  SERVICE wikibase:label { bd:serviceParam wikibase:language "en". }
}

based on sitelink count)
SELECT ?item ?itemLabel ?sitelinks WHERE {
  ?item wdt:P31 wd:Q3305213.  # instance of (P31) = painting (Q3305213)
  ?item wikibase:sitelinks ?sitelinks.
  SERVICE wikibase:label { bd:serviceParam wikibase:language "en". }
}
ORDER BY DESC(?sitelinks)
LIMIT 500

SELECT DISTINCT ?space ?spaceLabel ?woman ?womanLabel WHERE {
  ?space wdt:P31/wdt:P279* wd:Q119747 .  # public space or subclass
  ?space wdt:P138 ?woman .               # named after
  ?woman wdt:P31 wd:Q5 .                 # human
  ?woman wdt:P21 wd:Q6581072 .           # female
  SERVICE wikibase:label { bd:serviceParam wikibase:language "en". }
}

SELECT ?continent ?continentLabel ?river ?riverLabel ?length WHERE {
  {
    SELECT ?continent (MAX(?length) AS ?maxLength) WHERE {
      ?river wdt:P31/wdt:P279* wd:Q4022.          # instance/subclass of river
      ?river wdt:P2043 ?length.                   # length
      ?river wdt:P30 ?continent.                   # located in continent
      ?continent wdt:P31 wd:Q5107.                # instance of continent
    }
    GROUP BY ?continent
  }
  ?river wdt:P30 ?continent.
  ?river wdt:P2043 ?length.
  ?river wdt:P31/wdt:P279* wd:Q4022.
  FILTER(?length = ?maxLength)
  SERVICE wikibase:label { bd:serviceParam wikibase:language "en". }
}
ORDER BY ?continentLabel

SELECT ?route WHERE {
  wd:Q17015984 wdt:P527 ?route .
}

SELECT ?poem ?poemLabel ?language ?languageLabel ?firstLine WHERE {
  ?poem wdt:P31 wd:Q5185279.
  OPTIONAL { ?poem wdt:P407 ?language. }
  OPTIONAL { ?poem wdt:P1922 ?firstLine. }
  SERVICE wikibase:label { bd:serviceParam wikibase:language "en". }
}

SELECT ?color ?rgbValue WHERE {
  ?color wdt:P31 wd:Q1075.  # Instance of "color"
  ?color wdt:P688 ?rgbValue.  # Has RGB value
} GROUP BY ?color HAVING (COUNT(?rgbValue) > 1)
ORDER BY ?color

SELECT ?item ?itemLabel ?date ?materialLabel WHERE {
  ?item wdt:P31 wd:Q1330117.        # any item that is a fibula (brooch)
  ?item wdt:P170 wd:Q3320584.       # owned by or in the collection of Musée Saint-Raymond
  OPTIONAL { ?item wdt:P571 ?date. }
  OPTIONAL { ?item wdt:P186 ?material. }
  SERVICE wikibase:label { bd:serviceParam wikibase:language "en". }
}

SELECT ?item ?itemLabel WHERE {
  ?item wdt:P31 wd:Q5 .          # human individual
  ?item wdt:P8809 [] .           # has Electronic Enlightenment ID
  FILTER NOT EXISTS { ?item wikibase:sitelink [] }  # no Wikipedia article in any language
  SERVICE wikibase:label { bd:serviceParam wikibase:language "en". }
}

SELECT ?place ?placeLabel ?coordinates WHERE {
  ?person wdt:P31 wd:Q5;                # instance of human
           wdt:P106 wd:Q170584;         # occupation: witch
           wdt:P551 ?place.             # place of residence
  ?place wdt:P625 ?coordinates.         # get coordinates
  SERVICE wikibase:label { bd:serviceParam wikibase:language "en". }
}

SELECT ?state ?stateLabel ?cases ?date WHERE {
  ?state wdt:P31 wd:Q503624; wdt:P17 wd:Q668.
  ?state p:P1603 ?casesStatement.
  ?casesStatement ps:P1603 ?cases;
                 pq:P585 ?date.
  {
    SELECT ?state (MAX(?date) AS ?maxDate) WHERE {
      ?state wdt:P31 wd:Q503624; wdt:P17 wd:Q668.
      ?state p:P1603 ?casesStatement.
      ?casesStatement pq:P585 ?date.
    } GROUP BY ?state
  }
  FILTER(?date = ?maxDate)
  SERVICE wikibase:label { bd:serviceParam wikibase:language "en". }
}
ORDER BY DESC(?cases)

SELECT ?painting ?paintingLabel WHERE {
  ?painting wdt:P31 wd:Q3305213.  # Instance of painting
  ?painting rdfs:label ?paintingLabel.
  FILTER(CONTAINS(LCASE(?paintingLabel), "portrait"))
  FILTER NOT EXISTS {
    ?painting wdt:P180 ?depicts.   # Depicts something
  }
  SERVICE wikibase:label { bd:serviceParam wikibase:language "en". }
}

SELECT DISTINCT ?language ?languageLabel WHERE {
  ?lexeme a wikibase:Lexeme ;
          wikibase:lexicalCategory ?category ;
          dct:language ?language .
  SERVICE wikibase:label { bd:serviceParam wikibase:language "en". }
}

SELECT ?award ?label ?percentage WHERE {
  {
    SELECT ?award (COUNT(DISTINCT ?femaleRecipient) / COUNT(DISTINCT ?recipient) AS ?percentage) WHERE {
      ?award wdt:P31 wd:Q618779. # instance of award
      ?award wdt:P1027 ?recipient. # recipients of the award
      OPTIONAL { ?femaleRecipient wdt:P21 wd:Q6581072. } # female gender
    }
    GROUP BY ?award
    HAVING (COUNT(DISTINCT ?recipient) > 0)
  }
  SERVICE wikibase:label { bd:serviceParam wikibase:language "en". }
  ?award rdfs:label ?label.
}
ORDER BY DESC(?percentage)

