PREFIX wd: <http://www.wikidata.org/entity/>
PREFIX wdt: <http://www.wikidata.org/prop/direct/>

SELECT ?percentage WHERE {
  {
    SELECT (COUNT(DISTINCT ?person) AS ?total) WHERE {
      ?person wdt:P8024 [] .
    }
  }
  {
    SELECT (COUNT(DISTINCT ?woman) AS ?female) WHERE {
      ?woman wdt:P8024 [] ;
             wdt:P21 wd:Q6581072 .
    }
  }
  BIND((?female / ?total) * 100 AS ?percentage)
}

SELECT ?item ?itemLabel (COUNT(DISTINCT ?sitelink) AS ?languageCount) WHERE {
  ?item wdt:P31 wd:Q198891.  # instance of controversy
  ?sitelink schema:about ?item ;
            schema:isPartOf <https://en.wikipedia.org/> .
  SERVICE wikibase:label { bd:serviceParam wikibase:language "en". }
}
GROUP BY ?item ?itemLabel
ORDER BY DESC(?languageCount)

