  ?person wdt:P119 wd:Q784.  # buried in Pere Lachaise Cemetery
  ?person wdt:P19 ?placeOfBirth.  # place of birth
  ?placeOfBirth wdt:P625 ?coordinates.  # coordinates of place of birth
