SELECT ?genus ?genusLabel ?botanist ?botanistLabel WHERE {
  ?genus wdt:P31 wd:Q16521 ;         # instance of taxon
         wdt:P105 wd:Q34740 ;        # taxon rank: genus
         wdt:P138 ?botanist .        # named after
  ?botanist wdt:P106 wd:Q2374149 ;   # occupation: botanist
             wdt:P21 wd:Q6581072 .   # gender: female
  SERVICE wikibase:label { bd:serviceParam wikibase:language "en". }
}

