PREFIX wd: <http://www.wikidata.org/entity/>
PREFIX wdt: <http://www.wikidata.org/prop/direct/>
PREFIX wikibase: <http://wikiba.se/ontology#>
PREFIX bd: <http://www.bigdata.com/rdf#>

SELECT ?decade ?person ?personLabel WHERE {
  ?person wdt:P31 wd:Q5 ;
          wdt:P19/wdt:P17 wd:Q213 ;
          wdt:P20/wdt:P17 wd:Q183 ;
          wdt:P569 ?birthDate .
  BIND(YEAR(?birthDate) AS ?year)
  BIND(FLOOR(?year/10)*10 AS ?decade)
  SERVICE wikibase:label { bd:serviceParam wikibase:language "en". }
}
ORDER BY ?decade ?personLabel

SELECT ?monarch ?monarchLabel ?causeOfDeathLabel WHERE {
  ?monarch wdt:P39 wd:Q131151 .          # position held: monarch of England
  OPTIONAL { ?monarch wdt:P509 ?causeOfDeath . }  # cause of death
  SERVICE wikibase:label { bd:serviceParam wikibase:language "en". }
}

SELECT ?languageLabel (COUNT(?album) AS ?count) WHERE {
  ?album wdt:P31 wd:Q482994 ;       # music album
         wdt:P407 ?language .       # language of work or name
  SERVICE wikibase:label { bd:serviceParam wikibase:language "en". }
}
GROUP BY ?language ?languageLabel
ORDER BY DESC(?count)

SELECT ?person ?account1 ?account2 WHERE {
  ?person wdt:P31 wd:Q5.  # Instance of human
  ?person wdt:P553 ?account1.  # Social media account
  ?person wdt:P553 ?account2.  # Another social media account
  FILTER(STR(?account1) != STR(?account2) && LCASE(STR(?account1)) = LCASE(STR(?account2)))
}

SELECT DISTINCT (SUBSTR(?label, 1, 1) AS ?firstLetter) WHERE {
  ?software wdt:P31/wdt:P279* wd:Q341 .
  ?software rdfs:label ?label .
  FILTER(LANG(?label) = "en")
}
ORDER BY ?firstLetter

SELECT ?museum ?museumLabel WHERE {
  ?museum wdt:P31 wd:Q33506.
  ?museum wdt:P131 wd:Q171946.
  SERVICE wikibase:label { bd:serviceParam wikibase:language "en". }
}

SELECT ?category ?genderLabel (COUNT(DISTINCT ?winner) AS ?count) WHERE {
  ?nobel wdt:P31 wd:Q7191.          # instance of Nobel Prize
  ?nobel wdt:P361 ?category.        # part of prize category
  ?nobel wdt:P1027 ?winner.         # awarded to winner
  ?winner wdt:P21 ?gender.          # gender of winner
  SERVICE wikibase:label { bd:serviceParam wikibase:language "en". }
}
GROUP BY ?category ?gender ?genderLabel
ORDER BY ?category ?genderLabel

SELECT (COUNT(DISTINCT ?word) AS ?count) WHERE {
  ?word wdt:P31 wd:Q8171 ;          # instance of word
        wdt:P518 ?dictionary .      # has dictionary
  FILTER NOT EXISTS {
    ?word wdt:P518 ?otherDictionary .
    FILTER (?otherDictionary != ?dictionary)
  }
}

SELECT ?software ?softwareLabel ?field ?fieldLabel WHERE {
  ?software wdt:P31 wd:Q1130645.   # instance of open-source software
  ?software wdt:P31 wd:Q739627.    # instance of research software
  ?software wdt:P31 wd:Q739627.    # instance of research software (redundant, but ensures both)
  ?software wdt:P101 ?field.       # field of work
  SERVICE wikibase:label { bd:serviceParam wikibase:language "en". }
}

SELECT ?person ?personLabel ?deathDate ?sitelinkCount WHERE {
  ?person wdt:P31 wd:Q5 ;          # instance of human
          wdt:P570 ?deathDate .    # date of death
  FILTER(YEAR(?deathDate) = 2018)
  BIND(wikibase:sitelinks(?person) AS ?sitelinkCount)
  SERVICE wikibase:label { bd:serviceParam wikibase:language "en". }
}
ORDER BY DESC(?sitelinkCount)
LIMIT 1000

