SELECT ?river ?riverLabel ?length WHERE {
  ?river wdt:P31 wd:Q4022;  # instance of river
         wdt:P17 wd:Q142;   # country France
         wdt:P2043 ?length. # length
  FILTER NOT EXISTS {
    ?department wdt:P31 wd:Q6465; # department of France
               wdt:P138 ?river.   # named after the river
  }
  SERVICE wikibase:label { bd:serviceParam wikibase:language "fr". }
}
ORDER BY DESC(?length)
LIMIT 10

SELECT ?property (COUNT(?property) AS ?frequency) WHERE {
  ?library wdt:P31 wd:Q7075.  # instance of public library
  ?library ?property ?value.
}
GROUP BY ?property
ORDER BY DESC(?frequency)

SELECT ?scene ?sceneLabel WHERE {
  wd:Q1061470 wdt:P180 ?scene .  # Mediterranean Scenes (Q1061470) depicts something
  SERVICE wikibase:label { bd:serviceParam wikibase:language "en". }
