SELECT ?stage ?stageLabel WHERE {
  wd:Q33881 wdt:P31 wd:Q5.  # Tour de France is a human (instance of)
  ?stage wdt:P31 wd:Q5.     # Stage is a human (instance of)
  ?stage wdt:P361 wd:Q33881. # Stage is part of Tour de France
  SERVICE wikibase:label { bd:serviceParam wikibase:language "en". }
