SELECT ?subdivision ?subdivisionLabel ?population WHERE {
  ?subdivision wdt:P31 wd:Q10864048;  # instance of first-level administrative division
               wdt:P1082 ?population; # has population
               wdt:P194 ?legislature. # has legislative body
  FILTER NOT EXISTS { ?subdivision wdt:P194 [] } # no legislative body
  SERVICE wikibase:label { bd:serviceParam wikibase:language "en". }
}
ORDER BY DESC(?population)

SELECT ?propertyType (COUNT(?property) AS ?frequency) (SAMPLE(?property) AS ?exampleProperty) WHERE {
  ?property wikibase:propertyType ?propertyType .
}
GROUP BY ?propertyType
ORDER BY DESC(?frequency)

SELECT ?songTitle WHERE {
  ?song wdt:P31 wd:Q482994 ;  # instance of song
        wdt:P1476 ?songTitle . # title
  ?name wdt:P31 wd:Q11879590 ; # instance of female given name
        wdt:P1705 ?songTitle . # native label
}

SELECT ?property ?propertyLabel WHERE {
  ?property wdt:P31 wd:Q19847637.
  SERVICE wikibase:label { bd:serviceParam wikibase:language "en". }
}

SELECT DISTINCT ?personLabel ?propertyLabel ?otherLabel WHERE {
  VALUES ?person { wd:Q235025 wd:Q203712 }
  VALUES ?property { wdt:P26 wdt:P3373 wdt:P22 wdt:P25 wdt:P40 wdt:P1038 wdt:P451 wdt:P1290 wdt:P3448 wdt:P3449 }
  { ?person ?property ?other . } UNION { ?other ?property ?person . }
  ?other wdt:P31 wd:Q5 .
  SERVICE wikibase:label { bd:serviceParam wikibase:language "en". }
  FILTER(?person != ?other)
}

SELECT ?pubmedId ?pubmedLabel WHERE {
  ?disease wdt:P31 wd:Q12136 ;            # instance of disease
            wdt:P279* wd:Q18555224 ;      # subclass of renal cell carcinoma (Q18555224)
            wdt:P698 ?pubmedId .          # PubMed ID
  SERVICE wikibase:label { bd:serviceParam wikibase:language "en". }
}

SELECT ?stateLabel ?songLabel WHERE {
  ?state wdt:P31 wd:Q35657.   # instance of state of the United States
  ?state wdt:P85 ?song.       # official song
  SERVICE wikibase:label { bd:serviceParam wikibase:language "en". }
}
ORDER BY ?stateLabel

SELECT ?century ?person ?personLabel ?birthplace ?birthplaceLabel WHERE {
  # Find Basque people (people from the Basque Country, with Basque ethnicity, or born in Basque region)
  {
    ?person wdt:P172 wd:Q8191 .  # Ethnic group: Basque
  } UNION {
    ?person wdt:P19 ?birthplace .
    ?birthplace wdt:P17 wd:Q29 . # Birthplace located in Spain
    ?birthplace wdt:P131* wd:Q47588 . # Birthplace in Basque Country (autonomous community)
  } UNION {
    ?person wdt:P19 ?birthplace .
    ?birthplace wdt:P17 wd:Q31 . # Birthplace located in France
    ?birthplace wdt:P131* wd:Q188616 . # Birthplace in French Basque Country (Pyrénées-Atlantiques)
  }

  # Ensure they have a known birthplace (statement on Wikidata)
  ?person wdt:P19 ?birthplace .

  # Get death date to determine century
  ?person wdt:P570 ?deathDate .
  BIND(YEAR(?deathDate) AS ?deathYear)
  BIND(FLOOR(?deathYear / 100) + 1 AS ?centuryNum)
  BIND(CONCAT(STR(?centuryNum), "th century") AS ?century)

  # Ensure they have a Wikipedia article
  ?person wikibase:sitelink ?link .

  SERVICE wikibase:label { bd:serviceParam wikibase:language "en". }
}
GROUP BY ?century ?person ?personLabel ?birthplace ?birthplaceLabel
ORDER BY ?centuryNum ?personLabel

SELECT ?company ?companyLabel ?revenue WHERE {
  ?company wdt:P31/wdt:P279* wd:Q4830453. # instance or subclass of business enterprise
  ?company p:P2139 ?revenueStmt.          # revenue statement
  ?revenueStmt ps:P2139 ?revenue;         # revenue value
              wikibase:quantityUnit wd:Q4917. # unit: US dollar
  SERVICE wikibase:label { bd:serviceParam wikibase:language "en". }
}
ORDER BY DESC(?revenue)
LIMIT 10

SELECT ?type (COUNT(?id) AS ?count) WHERE {
  {
    SELECT ?item (SAMPLE(?twitterId) AS ?id) WHERE {
      ?item wdt:P31/wdt:P279* wd:Q35120 . # non-human entities
      ?item wdt:P2002 ?twitterId .
    } GROUP BY ?item
    BIND("Twitter ID" AS ?type)
  }
  UNION
  {
    SELECT ?item (SAMPLE(?facebookId) AS ?id) WHERE {
      ?item wdt:P31/wdt:P279* wd:Q35120 . # non-human entities
      ?item wdt:P2013 ?facebookId .
    } GROUP BY ?item
    BIND("Facebook ID" AS ?type)
  }
} GROUP BY ?type

SELECT ?person ?personLabel ?coordinates WHERE {
