SELECT ?sportLabel ?teamLabel ?coord WHERE {
  ?team wdt:P31 wd:Q12973014 ;   # instance of sports team
        wdt:P641 ?sport ;        # sport played
        wdt:P625 ?coord .        # coordinate location
  SERVICE wikibase:label { bd:serviceParam wikibase:language "en". }
}

SELECT ?chair ?chairLabel ?startTime ?endTime WHERE {
  ?chair wdt:P31 wd:Q5.
  ?chair wdt:P39 wd:Q108782485.
  ?chair p:P39 ?statement.
  ?statement ps:P39 wd:Q108782485.
  OPTIONAL { ?statement pq:P580 ?startTime. }
  OPTIONAL { ?statement pq:P582 ?endTime. }
  SERVICE wikibase:label { bd:serviceParam wikibase:language "en". }
}
ORDER BY ?startTime

SELECT ?city ?cityLabel (COUNT(DISTINCT ?river) AS ?numRivers) WHERE {
  ?city wdt:P31 wd:Q515 .
  ?city wdt:P206 ?river .
  ?river wdt:P31 wd:Q4022 .
  SERVICE wikibase:label { bd:serviceParam wikibase:language "en". }
}
GROUP BY ?city ?cityLabel
HAVING (COUNT(DISTINCT ?river) >= 2)
ORDER BY DESC(?numRivers)

SELECT ?institution ?institutionLabel ?coordinates ?type ?typeLabel WHERE {
  ?institution wdt:P31 wd:Q335402.  # Instance of GLAM institution
  ?institution wdt:P17 wd:Q145.     # Country: United Kingdom
  ?institution wdt:P131 ?location.  # Located in administrative territorial entity
  ?location wdt:P31 wd:Q15642541.   # Instance of country within the UK (Wales)
  OPTIONAL { ?institution wdt:P625 ?coordinates. }
  OPTIONAL { ?institution wdt:P31 ?type. }
  SERVICE wikibase:label { bd:serviceParam wikibase:language "en". }
}

SELECT ?economist ?birthYear ?deathYear WHERE {
  ?economist wdt:P106 wd:Q188094.   # occupation: economist
  ?economist wdt:P1938 ?gutenbergID. # Project Gutenberg ID
  OPTIONAL { ?economist wdt:P569 ?birthDate. }
  OPTIONAL { ?economist wdt:P570 ?deathDate. }
