PREFIX wd: <http://www.wikidata.org/entity/>
PREFIX wdt: <http://www.wikidata.org/prop/direct/>
PREFIX wikibase: <http://wikiba.se/ontology#>
PREFIX bd: <http://www.bigdata.com/rdf#>

SELECT ?item ?itemLabel WHERE {
  ?item wdt:P31/wdt:P279* wd:Q1440778 .
  ?item wdt:P195 wd:Q3331020 .
  SERVICE wikibase:label { bd:serviceParam wikibase:language "en". }
}

SELECT ?person ?personLabel ?birthday ?mother ?motherLabel ?deathDate WHERE {
  ?person wdt:P31 wd:Q5.                # person is a human
  ?person wdt:P569 ?birthday.            # person's date of birth
  ?person wdt:P25 ?mother.              # person's mother
  ?mother wdt:P570 ?deathDate.          # mother's date of death
  FILTER (MONTH(?birthday) = MONTH(?deathDate) && DAY(?birthday) = DAY(?deathDate))
  SERVICE wikibase:label { bd:serviceParam wikibase:language "en". }
}

SELECT ?person WHERE {
  ?person wdt:P31 wd:Q5.
  ?person wdt:P108 wd:Q162707.
  FILTER NOT EXISTS { ?person wdt:P6216 ?uid }
}

SELECT DISTINCT ?person ?personLabel WHERE {
  ?person wdt:P166 ?award .
  ?award wdt:P31/wdt:P279* wd:Q1382127 .
  FILTER NOT EXISTS { ?person wdt:P106 wd:Q188094 }
  SERVICE wikibase:label { bd:serviceParam wikibase:language "en". }
}

SELECT DISTINCT ?city WHERE {
  ?city wdt:P31 wd:Q515 ;          # instance of city
        wdt:P1082 ?pop .          # population
  FILTER(?pop > 1000000)           # population over 1 million
  FILTER NOT EXISTS {
    ?person wdt:P31 wd:Q5 ;        # a human
            wdt:P19 ?city .        # born in city
  }
  FILTER NOT EXISTS {
    ?person wdt:P31 wd:Q5 ;
            wdt:P20 ?city .        # died in city
  }
  FILTER NOT EXISTS {
    ?person wdt:P31 wd:Q5 ;
            wdt:P551 ?city .       # lived in city
  }
}

SELECT (COUNT(DISTINCT ?lake) AS ?count) WHERE {
  ?lake wdt:P31 wd:Q23397;                # instance of lake
        wdt:P17 wd:Q145;                  # country: United Kingdom
        wdt:P8989 ?ukLakesPortalId.       # UK Lakes Portal ID
}

SELECT ?country ?countryLabel ?languageLabel
WHERE {
  ?country wdt:P31 wd:Q3624078. # sovereign state
  ?country wdt:P30 wd:Q46.      # located in Africa continent
  ?country wdt:P37 ?language.   # official language
  SERVICE wikibase:label { bd:serviceParam wikibase:language "en". }
}
ORDER BY ?countryLabel

SELECT ?saint ?saintLabel ?feastDay (MONTH(?feastDay) AS ?month) (DAY(?feastDay) AS ?day) WHERE {
  ?saint wdt:P31 wd:Q43115.  # instance of saint
  ?saint wdt:P841 ?feastDay.  # feast day
  SERVICE wikibase:label { bd:serviceParam wikibase:language "en". }
}
ORDER BY ?month ?day

SELECT ?mission ?missionLabel WHERE {
  ?mission wdt:P31 wd:Q131079 . # instance of diplomatic mission
  ?mission wdt:P137 wd:Q145 . # operated by United Kingdom
  SERVICE wikibase:label { bd:serviceParam wikibase:language "en". }
}

SELECT ?person ?personLabel ?sitelinks WHERE {
  ?person wdt:P31 wd:Q5.                     # Instance of human
  ?person wikibase:sitelinks ?sitelinks.     # Get sitelink count
  SERVICE wikibase:label { bd:serviceParam wikibase:language "en". }
}
ORDER BY DESC(?sitelinks)                    # Most famous first (most sitelinks)
LIMIT 100

SELECT ?section ?sectionLabel WHERE {
  wd:Q180126 wdt:P527 ?section .  # Antonine Wall has parts (scheduled sections)
  ?section wdt:P31 wd:Q179271 .   # instance of scheduled monument
  SERVICE wikibase:label { bd:serviceParam wikibase:language "en". }
}

SELECT ?person ?personLabel ?occupationLabel ?placeOfBirth ?placeOfBirthLabel ?coordinates WHERE {
  ?person wdt:P31 wd:Q21542336 .          # person accused of witchcraft
  ?person wdt:P19 ?placeOfBirth .         # place of birth
  ?placeOfBirth wdt:P17 wd:Q22 .          # located in Scotland (country)
  ?placeOfBirth wdt:P625 ?coordinates .   # has geographic coordinates
  OPTIONAL { ?person wdt:P106 ?occupation . }  # optional occupation
  SERVICE wikibase:label { bd:serviceParam wikibase:language "en". }
}
LIMIT 1000

PREFIX wd: <http://www.wikidata.org/entity/>
PREFIX wdt: <http://www.wikidata.org/prop/direct/>
PREFIX p: <http://www.wikidata.org/prop/>
PREFIX wikibase: <http://wikiba.se/ontology#>
PREFIX ontolex: <http://www.w3.org/ns/lemon/ontolex#>
PREFIX rdfs: <http://www.w3.org/2000/01/rdf-schema#>

SELECT ?language ?languageLabel (COUNT(?lexeme) AS ?count)
WHERE {
  ?lexeme a ontolex:LexicalEntry ;
          wikibase:lexicalLanguage ?language .
  ?language wdt:P31 wd:Q34770 .   # instance of language
  FILTER NOT EXISTS {
    ?lexeme ?prop ?o .
    FILTER (STRSTARTS(STR(?prop), "http://www.wikidata.org/prop/"))
  }
  FILTER NOT EXISTS { ?lexeme ontolex:sense ?sense . }
  SERVICE wikibase:label { bd:serviceParam wikibase:language "en". }
}
GROUP BY ?language ?languageLabel
HAVING (COUNT(?lexeme) < 10)
ORDER BY DESC(?count)

SELECT ?museum ?museumLabel ?distance WHERE {
  wd:Q188740 wdt:P625 ?momaLoc .                          # Museum of Modern Art coordinates
  SERVICE wikibase:around {
    ?museum wdt:P625 ?museumLoc .                         # Nearby location
    bd:serviceParam wikibase:center ?momaLoc .
    bd:serviceParam wikibase:radius "1" .                 # 1 km radius
  }
  ?museum wdt:P31 wd:Q33506 .                             # Instance of museum
  FILTER(?museum != wd:Q188740)                           # Exclude MoMA itself
  SERVICE wikibase:label { bd:serviceParam wikibase:language "en" . }
  BIND(geof:distance(?momaLoc, ?museumLoc) AS ?distance)  # Compute distance (optional)
}

SELECT ?sibling ?siblingLabel WHERE {
  ?sibling wdt:P31 wd:Q5.
  ?sibling wdt:P166 wd:Q616393.
  ?sibling wdt:P3373 ?otherSibling.
  ?otherSibling wdt:P166 wd:Q616393.
  SERVICE wikibase:label { bd:serviceParam wikibase:language "en". }
}

SELECT ?name WHERE {
  ?person wdt:P31 wd:Q5.                    # instance of human
  ?person wdt:P21 wd:Q6581072.              # female gender (Q6581072)
  ?person wdt:P106 wd:Q156326.              # occupation: activist (Q156326)
  ?person wdt:P569 ?birthDate.              # date of birth
  ?person wdt:P937 wd:Q12585.              # country of citizenship: Latin America (Q12585)
  FILTER(YEAR(?birthDate) >= 1900 && YEAR(?birthDate) <= 1999)
  SERVICE wikibase:label { bd:serviceParam wikbase:language "en". }
  ?person rdfs:label ?name.
}

SELECT ?word ?genderLabel WHERE {
  ?word wdt:P31 wd:Q82059 .  # instance of French word
  ?word wdt:P5191 ?gender .  # grammatical gender
  SERVICE wikibase:label { bd:serviceParam wikibase:language "fr". }
}

SELECT ?item ?itemLabel WHERE {
  ?item wdt:P31 wd:Q5.
  ?item wdt:P570 "2001-08-25"^^xsd:dateTime.
  ?article schema:about ?item.
  ?article schema:isPartOf <https://en.wikipedia.org/>.
  SERVICE wikibase:label { bd:serviceParam wikibase:language "en". }
}

SELECT ?monument ?monumentLabel WHERE {
  wd:Q12726 wdt:P31 wd:Q5. # Ensure Loire-Atlantique is a department (optional)
  ?monument wdt:P131 wd:Q12726. # Located in Loire-Atlantique
  ?monument wdt:P31 wd:Q916333. # Instance of historical monument
  SERVICE wikibase:label { bd:serviceParam wikibase:language "en". }
}

SELECT ?painter ?painterLabel WHERE {
  ?painter wdt:P106 wd:Q1028181.  # instance of painter
  ?painter wdt:P570 ?deathDate.   # date of death
  FILTER(?deathDate < "1800-01-01T00:00:00Z"^^xsd:dateTime)
  SERVICE wikibase:label { bd:serviceParam wikibase:language "en". }
}

SELECT ?station ?stationLabel ?connection ?connectionLabel WHERE {
  ?station wdt:P31 wd:Q55488;          # instance of railway station
           wdt:P17 wd:Q55.             # country: Netherlands
  OPTIONAL { ?station wdt:P81 ?connection }  # connecting line
  SERVICE wikibase:label { bd:serviceParam wikibase:language "en". }
}

PREFIX wd: <http://www.wikidata.org/entity/>
PREFIX wdt: <http://www.wikidata.org/prop/direct/>
SELECT ?item ?creator WHERE {
  ?item wdt:P31 wd:Q146 .
  ?item wdt:P170 ?creator .
}

SELECT ?station ?stationLabel ?coord WHERE {
  ?station wdt:P31 wd:Q55488 ;   # instance of railway station
           wdt:P17 wd:Q25 ;      # country Wales
           wdt:P625 ?coord .     # coordinate location
  SERVICE wikibase:label { bd:serviceParam wikibase:language "en". }
}

SELECT ?game ?publicationDate WHERE {
  ?game wdt:P31 wd:Q7889;  # instance of video game
        wdt:P577 ?publicationDate.  # publication date
}

SELECT ?item ?itemLabel ?sitelinks WHERE {
  ?item wikibase:sitelinks ?sitelinks .
  FILTER(?sitelinks > 20)
  SERVICE wikibase:label { bd:serviceParam wikibase:language "en". }
}
ORDER BY DESC(?sitelinks)

SELECT ?department ?departmentLabel WHERE {
  ?department wdt:P31 wd:Q6465.  # instance of department of France
  SERVICE wikibase:label { bd:serviceParam wikibase:language "en". }
}

SELECT ?person ?personLabel ?twin ?twinLabel ?personPlaceLabel ?twinPlaceLabel WHERE {
  ?person p:P3373 [ ps:P3373 ?twin ; pq:P1880 wd:Q146786 ] .
  ?person wdt:P19 ?personPlace .
  ?twin wdt:P19 ?twinPlace .
  FILTER (?personPlace != ?twinPlace)
  SERVICE wikibase:label { bd:serviceParam wikibase:language "en". }
}

SELECT ?person ?personLabel WHERE {
  wd:Q23 wdt:P40* ?person .
  wd:Q207 wdt:P40* ?person .
  SERVICE wikibase:label { bd:serviceParam wikibase:language "en". }
}

SELECT ?place ?elevation WHERE {
  ?place wdt:P2044 ?elevation .
  FILTER(?elevation < 10)
}

SELECT ?award ?awardLabel ?pointInTime WHERE {
  wd:Q13364 p:P166 ?awardStatement.
  ?awardStatement ps:P166 ?award.
  OPTIONAL { ?awardStatement pq:P585 ?pointInTime. }
  SERVICE wikibase:label { bd:serviceParam wikibase:language "en". }
}

SELECT ?person ?personLabel ?age WHERE {
  ?person wdt:P106 wd:Q639669 .
  ?person wdt:P569 ?birth .
  ?person wdt:P570 ?death .
  BIND((YEAR(?death) - YEAR(?birth)) AS ?age)
  SERVICE wikibase:label { bd:serviceParam wikibase:language "en". }
}
ORDER BY ?age

SELECT ?detentionCenter ?detentionCenterLabel ?countryLabel WHERE {
  VALUES ?country { wd:Q77 wd:Q414 wd:Q298 } # Uruguay, Argentina, Chile
  ?detentionCenter wdt:P31 wd:Q6386997 . # instance of detention center
  ?detentionCenter wdt:P17 ?country .   # located in country
  ?detentionCenter wdt:P31 wd:Q10833348 . # instance of torture site
  SERVICE wikibase:label { bd:serviceParam wikibase:language "en". }
}

SELECT DISTINCT ?country ?countryLabel ?personLabel WHERE {
  ?country wdt:P31 wd:Q6256.          # instance of sovereign state
  ?country wdt:P138 ?person.          # named after something
  ?person wdt:P31 wd:Q5.              # that something is a human
  SERVICE wikibase:label { bd:serviceParam wikibase:language "en". }
}

