PREFIX wd: <http://www.wikidata.org/entity/>
PREFIX wdt: <http://www.wikidata.org/prop/direct/>
PREFIX p: <http://www.wikidata.org/prop/>
PREFIX pq: <http://www.wikidata.org/prop/qualifier/>
PREFIX ps: <http://www.wikidata.org/prop/statement/>

SELECT ?justiceLabel ?dob WHERE {
  VALUES ?position { wd:Q1152687 wd:Q11178 } # Associate Justice and Chief Justice
  ?justice p:P39 ?stmt.
  ?stmt ps:P39 ?position.
  FILTER NOT EXISTS { ?stmt pq:P582 ?end. }
  OPTIONAL { ?justice wdt:P569 ?dob. }
  SERVICE wikibase:label { bd:serviceParam wikibase:language "en". }
}

SELECT ?firstName (COUNT(DISTINCT ?person) AS ?count) WHERE {
  ?person wdt:P31 wd:Q5.
  ?person wdt:P19/wdt:P131* wd:Q1171.
  ?person wdt:P735 ?givenName.
  ?givenName wdt:P31 wd:Q202444.
  SERVICE wikibase:label { bd:serviceParam wikibase:language "en". }
  BIND(STR(?givenName) AS ?firstName)
}
GROUP BY ?firstName
ORDER BY DESC(?count)

SELECT DISTINCT ?inspirationLabel WHERE {
  {
    { ?item wdt:P31 wd:Q523 }      # star
    UNION
    { ?item wdt:P31 wd:Q318 }      # galaxy
    UNION
    { ?item wdt:P31 wd:Q186686 }   # star cluster
    UNION
    { ?item wdt:P31 wd:Q50941 }    # nebula
  }
  ?item wdt:P941 ?inspiration.     # inspired by
  SERVICE wikibase:label { bd:serviceParam wikibase:language "en". }
}

SELECT ?praenomen ?count WHERE {
  ?person wdt:P31 wd:Q5 .
  ?person wdt:P2358 ?praenomen .
} GROUP BY ?praenomen
ORDER BY DESC(COUNT(?person))
LIMIT 10

SELECT DISTINCT ?landlockedCountry ?landlockedCountryLabel ?neighbor ?neighborLabel WHERE {
  # ?landlockedCountry is a sovereign state
  ?landlockedCountry wdt:P31 wd:Q3624078 .

  # Ensure it is landlocked: no direct border with a sea or ocean via P206
  FILTER NOT EXISTS {
    ?landlockedCountry wdt:P206 ?water .
    ?water wdt:P31/wdt:P279* wd:Q165 .  # Q165 = sea
  }
  FILTER NOT EXISTS {
    ?landlockedCountry wdt:P206 ?water .
    ?water wdt:P31/wdt:P279* wd:Q9430 .  # Q9430 = ocean
  }

  # Find a neighbor country that is coastal
  ?landlockedCountry wdt:P47 ?neighbor .
  ?neighbor wdt:P31 wd:Q3624078 .

  # Neighbor must be coastal: has a direct border with a sea or ocean
  FILTER EXISTS {
    ?neighbor wdt:P206 ?water2 .
    ?water2 wdt:P31/wdt:P279* wd:Q165 .
  }

  # Get labels
  SERVICE wikibase:label { bd:serviceParam wikibase:language "en". }
}
ORDER BY ?landlockedCountryLabel

SELECT?placeLabel ?demonym WHERE {
  wd:Q60 wdt:P1549 ?demonym.
  SERVICE wikibase:label { bd:serviceParam wikibase:language "en". }
}

SELECT ?school ?studentPopulation WHERE {
  ?school wdt:P31 wd:Q3918;  # instance of drama school
          wdt:P2196 ?studentPopulation.  # student population
}
ORDER BY DESC(?studentPopulation)
LIMIT 10

SELECT ?person ?personLabel ?society ?societyLabel WHERE {
  ?person wdt:P463 ?society .
  ?society wdt:P31 wd:Q3557396 . # learned society
  ?person wdt:P570 ?deathDate .
  FILTER(?deathDate < "1800-01-01T00:00:00Z"^^xsd:dateTime)
  SERVICE wikibase:label { bd:serviceParam wikibase:language "en". }
}

SELECT ?cemetery ?cemeteryLabel ?church ?churchLabel WHERE {
  ?cemetery wdt:P31 wd:Q39614 .          # instance of cemetery
  ?church wdt:P31 wd:Q16970 .            # instance of church building
  ?cemetery wdt:P47 ?church .            # cemetery adjacent to church
  ?cemetery wdt:P17 wd:Q142 .            # cemetery located in France
  ?church wdt:P17 wd:Q142 .              # church located in France
  SERVICE wikibase:label { bd:serviceParam wikibase:language "en". }
}

PREFIX wd: <http://www.wikidata.org/entity/>
PREFIX wdt: <http://www.wikidata.org/prop/direct/>
PREFIX wikibase: <http://wikiba.se/ontology#>
PREFIX bd: <http://www.bigdata.com/rdf#>

SELECT ?work ?workLabel WHERE {
  ?work wdt:P58 wd:Q1234799 .
  SERVICE wikibase:label { bd:serviceParam wikibase:language "en". }
}

SELECT ?twitterHandle WHERE {
  ?mp wdt:P31 wd:Q5;                # instance of human
      wdt:P39 wd:Q16707842;         # position held: Member of Parliament of the United Kingdom
      wdt:P2002 ?twitterHandle.     # Twitter username
  FILTER NOT EXISTS { ?mp wdt:P582 ?endTime }  # no end time (currently in office)
}

PREFIX wd: <http://www.wikidata.org/entity/>
PREFIX wdt: <http://www.wikidata.org/prop/direct/>

SELECT ?incident ?location ?injured WHERE {
  ?incident wdt:P31/wdt:P279* wd:Q120789.
  OPTIONAL { ?incident wdt:P276 ?location. }
  OPTIONAL { ?incident wdt:P1331 ?injured. }
}

PREFIX wd: <http://www.wikidata.org/entity/>
PREFIX wdt: <http://www.wikidata.org/prop/direct/>
PREFIX p: <http://www.wikidata.org/prop/>
PREFIX ps: <http://www.wikidata.org/prop/statement/>
PREFIX pq: <http://www.wikidata.org/prop/qualifier/>
PREFIX rdfs: <http://www.w3.org/2000/01/rdf-schema#>

SELECT ?winner ?winnerLabel ?image ?pointInTime WHERE {
  ?winner p:P166 ?awardStatement .
  ?awardStatement ps:P166 wd:Q2419191 .  # Theatre World Award
  OPTIONAL { ?awardStatement pq:P585 ?pointInTime . }
  OPTIONAL { ?winner wdt:P18 ?image . }
  SERVICE wikibase:label { bd:serviceParam wikibase:language "en". }
}
ORDER BY ?pointInTime

SELECT ?surname ?surnameLabel (COUNT(DISTINCT ?human) AS ?count)
WHERE {
  ?human wdt:P31 wd:Q5.
  ?human wdt:P734 ?surname.
  SERVICE wikibase:label { bd:serviceParam wikibase:language "en". }
}
GROUP BY ?surname ?surnameLabel
ORDER BY DESC(?count)
LIMIT 20

SELECT ?item ?itemLabel WHERE {
  { # Rhyme by matching last two characters of the label
    SELECT ?item ?itemLabel WHERE {
      ?item wdt:P31 wd:Q3305213.  # instance of artwork
      ?item rdfs:label ?itemLabel.
      FILTER((LANG(?itemLabel)) = "en").
    }
    GROUP BY ?item ?itemLabel
    HAVING (STRENDS(?itemLabel, SUBSTR(?itemLabel, STRLEN(?itemLabel)-1, 2)))
  }
  UNION
  { # Rhyme by matching last three characters (for longer words)
    SELECT ?item ?itemLabel WHERE {
      ?item wdt:P31 wd:Q3305213.
      ?item rdfs:label ?itemLabel.
      FILTER((LANG(?itemLabel)) = "en").
    }
    GROUP BY ?item ?itemLabel
    HAVING (STRENDS(?itemLabel, SUBSTR(?itemLabel, STRLEN(?itemLabel)-2, 3)))
  }
}
LIMIT 100

SELECT ?composerLabel (COUNT(?film) AS ?filmCount) WHERE {
  ?composer wdt:P106 wd:Q1417370 .
  ?film wdt:P31 wd:Q11424 .
  ?film wdt:P86 ?composer .
}
GROUP BY ?composer ?composerLabel
HAVING (COUNT(?film) > 100)
SERVICE wikibase:label { bd:serviceParam wikibase:language "en". }

SELECT DISTINCT ?member ?memberLabel ?ancestor ?ancestorLabel WHERE {
  VALUES ?position { wd:Q16707842 wd:Q18178272 }
  VALUES ?ancestorProp { wdt:P1025 wdt:P1297 wdt:P22 wdt:P25 wdt:P1038 }
  ?member wdt:P39 ?position .
  ?member ?ancestorProp ?ancestor .
  ?ancestor wdt:P31 wd:Q4271324 .
  SERVICE wikibase:label { bd:serviceParam wikibase:language "en". }
}
LIMIT 100

SELECT DISTINCT ?property ?propertyLabel WHERE {
  {
    ?preprint wdt:P31 wd:Q580922 .
    ?preprint ?property ?article .
    ?article wdt:P31 wd:Q13442814 .
  } UNION {
    ?article wdt:P31 wd:Q13442814 .
    ?article ?property ?preprint .
    ?preprint wdt:P31 wd:Q580922 .
  }
  SERVICE wikibase:label { bd:serviceParam wikibase:language "en". }
}
ORDER BY ?property

SELECT ?senator ?senatorLabel ?institution ?institutionLabel WHERE {
  ?senator wdt:P39 wd:Q4416090. # US senator
  ?senator wdt:P69 ?institution. # educated at
  ?institution wdt:P31 wd:Q3918. # educational institution
  SERVICE wikibase:label { bd:serviceParam wikibase:language "en". }
}
ORDER BY ?senatorLabel

SELECT DISTINCT ?author ?authorLabel WHERE {
  # Find papers connected to Paul Erdős
  ?paper wdt:P31 wd:Q13442814 .  # Instance of scientific article
  ?paper wdt:P50 wd:Q173292 .    # Author includes Paul Erdős

  # Find other authors of those papers
  ?paper wdt:P50 ?author .

  # Exclude Paul Erdős himself
  FILTER(?author != wd:Q173292)

  SERVICE wikibase:label { bd:serviceParam wikibase:language "en". }
}

PREFIX schema: <http://schema.org/>
PREFIX wikibase: <http://wikiba.se/ontology#>
SELECT DISTINCT ?person ?personLabel WHERE {
  ?person wdt:P31 wd:Q5 .              # human
  ?person wdt:P21 wd:Q6581072 .        # female
  { ?person wdt:P106 wd:Q5716684 }     # dancer
    UNION
  { ?person wdt:P106 wd:Q2490358 }     # choreographer
  ?enwiki schema:about ?person ; schema:isPartOf <https://en.wikipedia.org/> .
  FILTER NOT EXISTS {
    ?frwiki schema:about ?person ; schema:isPartOf <https://fr.wikipedia.org/> .
  }
  SERVICE wikibase:label { bd:serviceParam wikibase:language "en". }
}
LIMIT 100

SELECT DISTINCT ?universityLabel WHERE {
  ?person wdt:P106 wd:Q121998 ;    # occupation: ambassador
          wdt:P27 wd:Q145 ;        # country of citizenship: United Kingdom
          wdt:P69 ?university .    # educated at
  SERVICE wikibase:label { bd:serviceParam wikibase:language "en". }
}
ORDER BY ?universityLabel

SELECT ?lighthouse ?coords WHERE {
  ?lighthouse wdt:P31 wd:Q39715;          # instance of lighthouse
             wdt:P17 wd:Q18;             # country: South America (Q18)
             wdt:P625 ?coords.           # coordinate location
}

SELECT ?language1 ?language2 (COUNT(?lexeme) AS ?overlapCount) WHERE {
  ?lexeme wikibase:lexicalCategory ?category ;
          dct:language ?language1 ;
          dct:language ?language2 .
  FILTER(?language1 != ?language2)
}
GROUP BY ?language1 ?language2
ORDER BY DESC(?overlapCount)

SELECT ?episode ?episodeLabel ?subject ?subjectLabel WHERE {
  ?episode wdt:P31 wd:Q21191270;             # instance of episode of television series
           wdt:P179 wd:Q209295;              # part of The West Wing
           wdt:P921 ?subject.                # main subject
  SERVICE wikibase:label { bd:serviceParam wikibase:language "en". }
}
ORDER BY ?episode

SELECT ?place ?placeLabel ?englishName ?welshName WHERE {
  # Places that have both English and Welsh names
  ?place wdt:P31 wd:Q486972.          # Instance of: human settlement (optional, can be broader)
  ?place wdt:P1448 ?englishName.        # Official name (English)
  ?place wdt:P1448 ?welshName.         # Official name (Welsh) - same property for both languages
  FILTER(LANG(?englishName) = "en")    # Filter English names
  FILTER(LANG(?welshName) = "cy")      # Filter Welsh names

  SERVICE wikibase:label { bd:serviceParam wikbase:language "en,cy". }
}

SELECT ?property ?propertyLabel (COUNT(?item) AS ?count) WHERE {
  ?item wdt:P31 wd:Q4006. # Instance of map
  ?item ?property ?value.
  ?property a wikibase:Property.
  SERVICE wikibase:label { bd:serviceParam wikibase:language "en". }
}
GROUP BY ?property ?propertyLabel
ORDER BY DESC(?count)
LIMIT 20

SELECT ?museum ?museumLabel ?location WHERE {
  SERVICE wikibase:around {
    ?museum wdt:P31 wd:Q33506;
            wdt:P625 ?location.
    bd:serviceParam wikibase:center "Point(0 0)"^^geo:wktLiteral;
                    wikibase:radius "20".
  }
  SERVICE wikibase:label { bd:serviceParam wikibase:language "en". }
}

SELECT ?place ?placeLabel ?distance WHERE {
  SERVICE wikibase:around {
    ?place wdt:P625 ?location.
    bd:serviceParam wikibase:center "Point(2.29 48.87)"^^geo:wktLiteral.
    bd:serviceParam wikibase:radius "10". # radius in km
  }
  BIND(geof:distance("Point(2.29 48.87)"^^geo:wktLiteral, ?location) AS ?distance)
  SERVICE wikibase:label { bd:serviceParam wikibase:language "en". }
}
ORDER BY ?distance

SELECT ?language ?languageLabel WHERE {
  wd:Q142 wdt:P37 ?language.
  SERVICE wikibase:label { bd:serviceParam wikibase:language "en". }
}

SELECT ?item ?itemLabel ?coords WHERE {
  ?item wdt:P31/wdt:P279* wd:Q744099 .   # hillfort or subclass thereof
  ?item wdt:P17 wd:Q145 .                # located in United Kingdom
  ?item wdt:P2679 ?designPlan .          # has design plan property
  ?item wdt:P625 ?coords .               # coordinates
  SERVICE wikibase:label { bd:serviceParam wikibase:language "en". }
}

SELECT DISTINCT ?person ?personLabel WHERE {
  ?person wdt:P31 wd:Q5.          # human
  ?person wdt:P21 wd:Q6581072.    # female
  ?person wdt:P19 ?place.         # place of birth
  ?place wdt:P17 wd:Q145.         # located in the United Kingdom
  SERVICE wikibase:label { bd:serviceParam wikibase:language "en". }
}

SELECT ?person ?personLabel ?grave ?graveLabel ?deathDate WHERE {
  ?grave wdt:P31/wdt:P279* wd:Q173885 .          # instance or subclass of grave
  ?grave wdt:P276 wd:Q311 .                       # located in Père Lachaise Cemetery
  { ?grave wdt:P138 ?person } UNION { ?grave wdt:P825 ?person } .  # named after or dedicated to the person
  ?person wdt:P570 ?deathDate .                   # date of death
  FILTER(?deathDate >= "1800-01-01T00:00:00Z"^^xsd:dateTime && 
         ?deathDate <= "1849-12-31T23:59:59Z"^^xsd:dateTime)
  SERVICE wikibase:label { bd:serviceParam wikibase:language "en". }
}
ORDER BY ?deathDate

SELECT ?person ?personLabel ?birthDate ?positionLabel WHERE {
  ?person wdt:P106 wd:Q82955.         # occupation: politician
  ?person wdt:P27 wd:Q38.             # country of citizenship: Italy
  ?person wdt:P569 ?birthDate.        # date of birth
  ?person wdt:P39 ?position.          # position held
  ?position wdt:P279 wd:Q83307.       # subclass of: minister
  FILTER( (?birthDate >= "1944-01-01T00:00:00Z"^^xsd:dateTime) && (?birthDate <= "1974-12-31T23:59:59Z"^^xsd:dateTime) )
  SERVICE wikibase:label { bd:serviceParam wikibase:language "en". }
}
ORDER BY ?personLabel

SELECT ?person ?personLabel (MIN(?start) AS ?firstTermStart) WHERE {
  ?person p:P39 ?statement.
  ?statement ps:P39 wd:Q11696.
  ?statement pq:P580 ?start.
  SERVICE wikibase:label { bd:serviceParam wikibase:language "en". }
}
GROUP BY ?person ?personLabel
ORDER BY ?firstTermStart

SELECT ?image WHERE {
  { wd:Q1685398 wdt:P18 ?image. }
  UNION
  { ?astrolabe wdt:P170 wd:Q1685398;
               wdt:P31 wd:Q172790;
               wdt:P18 ?image. }
}

SELECT ?region ?regionLabel ?percentage ?location WHERE {
  # Subquery to get the percentage of Welsh speakers for each region
  {
    SELECT ?region (MAX(?population) AS ?totalPopulation) (SUM(?welshSpeakers) AS ?totalWelshSpeakers) 
           (ROUND(SUM(?welshSpeakers) * 100.0 / MAX(?population)) AS ?percentage) WHERE {
      # Regions in Wales (administrative divisions)
      ?region wdt:P31 wd:Q10864048;  # administrative territorial entity
              wdt:P17 wd:Q145.       # country: United Kingdom
      # Filter for regions within Wales
      ?region wdt:P131 wd:Q25.       # located in the administrative territorial entity: Wales

      # Population data
      ?region p:P1082 ?populationStatement.
      ?populationStatement ps:P1082 ?population;
                          pq:P585 ?populationDate.
      # Get the most recent population data
      OPTIONAL { ?populationStatement pq:P585 ?populationDate. }
      FILTER NOT EXISTS {
        ?region p:P1082 ?otherPopStatement.
        ?otherPopStatement ps:P1082 ?otherPop;
                          pq:P585 ?otherPopDate.
        FILTER(?otherPopDate > ?populationDate)
      }

      # Welsh speakers data (property P1410: number of speakers)
      ?region p:P1410 ?welshStatement.
      ?welshStatement ps:P1410 ?welshSpeakers;
                     pq:P518 ?languageGroup.
      # Filter for Welsh language (Q9309)
      ?languageGroup wdt:P31 wd:Q9309.  # Welsh language
      # Get the most recent data
      OPTIONAL { ?welshStatement pq:P585 ?welshDate. }
      FILTER NOT EXISTS {
        ?region p:P1410 ?otherWelshStatement.
        ?otherWelshStatement ps:P1410 ?otherWelsh;
                            pq:P585 ?otherWelshDate;
                            pq:P518 ?otherLanguageGroup.
        ?otherLanguageGroup wdt:P31 wd:Q9309.
        FILTER(?otherWelshDate > ?welshDate)
      }
    }
    GROUP BY ?region
  }

  # Get location coordinates for the map
  ?region wdt:P625 ?location.

  SERVICE wikibase:label { bd:serviceParam wikibase:language "en". }
}
ORDER BY DESC(?percentage)

SELECT ?language ?languageLabel ?country ?countryLabel WHERE {
  ?language wdt:P31 wd:Q34770.  # Instance of language
  ?language wdt:P17 ?country.   # Country where language is spoken
  SERVICE wikibase:label { bd:serviceParam wikibase:language "en". }
}
ORDER BY ?languageLabel

SELECT ?person ?personLabel ?birthDate WHERE {
  ?person wdt:P31 wd:Q5.                # instance of human
  ?person wdt:P569 ?birthDate.          # date of birth
  FILTER(
    MONTH(?birthDate) = 1 &&            # born in January
    (YEAR(?birthDate) % 400 = 0 ||      # leap year rule
     (YEAR(?birthDate) % 4 = 0 && 
      YEAR(?birthDate) % 100 != 0))
  )
  SERVICE wikibase:label { bd:serviceParam wikibase:language "en". }
}
ORDER BY ?birthDate

SELECT ?author ?authorLabel ?item ?itemLabel WHERE {
  ?author wdt:P108 wd:Q838735. # affiliated with Coventry University
  ?author wdt:P50 ?item. # author of an item
  SERVICE wikibase:label { bd:serviceParam wikibase:language "en". }
}

SELECT ?monarch ?monarchLabel ?placeOfDeathLabel ?dateOfDeath WHERE {
  ?monarch wdt:P31 wd:Q5;                # instance of human
           wdt:P106 wd:Q116;             # occupation: monarch
           wdt:P27 wd:Q35;               # country of citizenship: Denmark
           wdt:P570 ?dateOfDeath;        # date of death
           wdt:P20 ?placeOfDeath.        # place of death
  SERVICE wikibase:label { bd:serviceParam wikibase:language "en". }
}
ORDER BY ?dateOfDeath

SELECT ?part ?partLabel WHERE {
  wd:WP28 wdt:P527 ?part .
  SERVICE wikibase:label { bd:serviceParam wikibase:language "en". }
}

SELECT ?month ?poem ?poemLabel WHERE {
  wd:Q7241 wdt:P800 ?poem . # wd:Q7241 is Rabindranath Tagore, wdt:P800 is notable work
  ?poem wdt:P31 wd:Q5185279 . # Q5185279 is poem
  ?poem wdt:P577 ?publicationDate . # wdt:P577 is publication date
  BIND(MONTH(?publicationDate) AS ?month)
  SERVICE wikibase:label { bd:serviceParam wikibase:language "en". }
}
ORDER BY ?month ?poemLabel

SELECT ?restaurant ?restaurantLabel ?location ?starCount WHERE {
  ?restaurant wdt:P31 wd:Q11707;                # instance of restaurant
              wdt:P17 wd:Q39;                   # country: Switzerland
              wdt:P625 ?location;               # coordinate location
              wdt:P1431 ?starCount.             # Michelin star rating
  SERVICE wikibase:label { bd:serviceParam wikibase:language "en". }
}

SELECT DISTINCT ?birthplace ?birthplaceLabel WHERE {
  ?person wdt:P106 wd:Q188094.
  ?person wdt:P19 ?birthplace.
  SERVICE wikibase:label { bd:serviceParam wikibase:language "en". }
}
LIMIT 100

SELECT ?person ?personLabel ?dateOfDeath WHERE {
  ?person wdt:P31 wd:Q5.                # instance of human
  ?person wdt:P570 ?dateOfDeath.        # date of death
  FILTER(?dateOfDeath >= "1969-01-01"^^xsd:dateTime && ?dateOfDeath <= "1970-12-31"^^xsd:dateTime)
  SERVICE wikibase:label { bd:serviceParam wikibase:language "en". }
}
ORDER BY ?dateOfDeath

SELECT ?headOfGovernment ?headOfGovernmentLabel ?startTime ?endTime (xsd:integer(?endTime - ?startTime) AS ?durationDays) WHERE {
  # Find instances of head of government of France
  ?headOfGovernment wdt:P31 wd:Q5;                    # Instance of human
                    wdt:P39 wd:Q15964890.             # Position held: Prime Minister of France
  OPTIONAL { ?headOfGovernment p:P39 ?positionStmt. }
  ?positionStmt ps:P39 wd:Q15964890;                  # Statement for Prime Minister
                pq:P580 ?startTime.                   # Start time
  OPTIONAL { ?positionStmt pq:P582 ?endTime. }        # End time (optional for current)
  FILTER(BOUND(?endTime))                             # Only those with end time (historical)
  SERVICE wikibase:label { bd:serviceParam wikibase:language "en". }
}
ORDER BY DESC(?durationDays)
LIMIT 10

SELECT ?route ?routeLabel ?coords WHERE {
  ?route wdt:P31 wd:Q15079663 ;   # instance of tramway route
         wdt:P17 wd:Q142 ;        # country France
         wdt:P625 ?coords .       # coordinate location
  SERVICE wikibase:label { bd:serviceParam wikibase:language "en". }
}

SELECT ?opening ?openingLabel ?sitelinks WHERE {
  ?opening wdt:P31 wd:Q108129 .
  ?opening wikibase:sitelinks ?sitelinks .
  SERVICE wikibase:label { bd:serviceParam wikibase:language "en". }
}
ORDER BY DESC(?sitelinks)
LIMIT 10

SELECT ?country ?countryLabel ?painting ?paintingLabel WHERE {
  ?painting wdt:P31 wd:Q3305213.
  ?painting wdt:P17 ?country.
  ?painting wdt:P135 wd:Q37068.
  ?painting wdt:P2048 ?height.
  ?country wdt:P31 wd:Q3624078.
  SERVICE wikibase:label { bd:serviceParam wikibase:language "en". }
}
