LIMIT 10

SELECT ?woman ?womanLabel WHERE {
  # Find women with Wikipedia pages
  ?woman wdt:P31 wd:Q5 .                  # instance of human
  ?woman wdt:P21 wd:Q6581072 .            # female gender
  ?woman wdt:P27 wd:Q258 .               # country of citizenship: South Africa
  ?woman wdt:P569 ?birthDate .           # date of birth (optional, for filtering)

  # Ensure they have a Wikipedia page
  ?article schema:about ?woman .
  ?article schema:isPartOf <https://en.wikipedia.org/> .

  # Exclude those with a Wikiquote page
  FILTER NOT EXISTS {
    ?wikiquote schema:about ?woman .
    ?wikiquote schema:isPartOf <https://en.wikiquote.org/> .
  }

  SERVICE wikibase:label { bd:serviceParam wikibase:language "en". }
}

SELECT ?place ?placeLabel ?location WHERE {
  SERVICE wikibase:around {
    ?place wdt:P625 ?location.
    bd:serviceParam wikibase:center "Point(13.4050 52.5200)"^^geo:wktLiteral. # Replace with your coordinates
    bd:serviceParam wikibase:radius "1". # Radius in kilometers
  }
  ?place wdt:P31/wdt:P279* wd:Q226982. # Instance or subclass of public space
  ?place wdt:P31/wdt:P279* wd:Q17350442. # Instance or subclass of table tennis table
  SERVICE wikibase:label { bd:serviceParam wikibase:language "en". }
}

SELECT ?movie ?movieLabel ?videoLink WHERE {
  ?movie wdt:P31 wd:Q11424.        # Instance of (P31) film (Q11424)
  ?movie wdt:P1651 ?videoLink.     # YouTube video ID (P1651)
  SERVICE wikibase:label { bd:serviceParam wikibase:language "en". }
}
LIMIT 10

SELECT ?lexeme ?translationCount WHERE {
  {
    SELECT ?lexeme (COUNT(?translation) AS ?translationCount) WHERE {
      ?lexeme a wikibase:Lexeme .
      OPTIONAL { ?lexeme dct:source ?translation . }
    } GROUP BY ?lexeme
  }
} ORDER BY DESC(?translationCount) LIMIT 100

SELECT ?monument ?monumentLabel ?personLabel WHERE {
  ?monument wdt:P31/wdt:P279* wd:Q4989906. # instance/subclass of monument
  ?monument wdt:P138 ?person. # named after a person
  FILTER NOT EXISTS {
    ?monument ?p ?person. # any other connection
    FILTER(?p != wdt:P138) # exclude the naming relation
  }
  SERVICE wikibase:label { bd:serviceParam wikibase:language "en". }
}

SELECT ?language ?languageLabel WHERE {
  wd:Q55 wdt:P2936 ?language.
  SERVICE wikibase:label { bd:serviceParam wikibase:language "en". }
}

SELECT ?language ?languageLabel ?followerCount ?date WHERE {
  # Find programming languages
  ?language wdt:P31 wd:Q9143.  # instance of programming language

  # Get Twitter follower count property (P868)
  ?language p:P868 ?followerStatement.
  ?followerStatement ps:P868 ?followerCount.

  # Get the point in time for the count (optional, but useful for "latest")
  OPTIONAL { ?followerStatement pq:P585 ?date. }

  # Filter to get the latest count per language (if multiple)
  {
    SELECT ?language (MAX(?date) AS ?maxDate) WHERE {
      ?language wdt:P31 wd:Q9143.
      ?language p:P868 ?statement.
      OPTIONAL { ?statement pq:P585 ?date. }
    } GROUP BY ?language
  }
  FILTER(?date = ?maxDate || (!BOUND(?date) && !BOUND(?maxDate)))

  SERVICE wikibase:label { bd:serviceParam wikibase:language "en". }
}
ORDER BY DESC(?followerCount)

SELECT ?language ?languageCode WHERE {
  ?lemma dct:language ?language .
  ?language wdt:P218 ?languageCode .
}
GROUP BY ?language ?languageCode

SELECT DISTINCT ?itemType ?itemTypeLabel WHERE {
  ?item wdt:P31 ?itemType ;
        wdt:P276 wd:Q636400 .  # wd:Q636400 is the Ashmolean Museum
  SERVICE wikibase:label { bd:serviceParam wikibase:language "en". }
}

SELECT ?astrolabe ?astrolabeLabel ?diameter ?date WHERE {
  ?astrolabe wdt:P31 wd:Q188055.
  ?astrolabe wdt:P1106 ?diameter.
  ?astrolabe wdt:P571 ?date.
  SERVICE wikibase:label { bd:serviceParam wikibase:language "en". }
}
ORDER BY ?date

SELECT ?letter ?count WHERE {
  {
    SELECT ?letter (COUNT(?alphabet) AS ?count) WHERE {
      ?alphabet wdt:P898 ?letter .
    }
    GROUP BY ?letter
  }
  FILTER(?letter = "a"@en)  // Replace "a" with the specific letter you want
}

SELECT ?descendant ?descendantLabel WHERE {
  # The Achaemenid dynasty (Q121748) is the subject
  wd:Q121748 wdt:P40 ?descendant .  # P40: child
  SERVICE wikibase:label { bd:serviceParam wikibase:language "en". }
}

SELECT ?work ?workLabel ?publicationDate WHERE {
  ?work wdt:P50 wd:Q9068.  # Q9068 is Voltaire
  OPTIONAL { ?work wdt:P577 ?publicationDate . }
  SERVICE wikibase:label { bd:serviceParam wikibase:language "en". }
}

SELECT DISTINCT ?property ?propertyLabel WHERE {
  ?file wdt:P31/wdt:P279* wd:Q235557 .  # instances and subclasses of file format
  ?file ?property ?value .
  SERVICE wikibase:label { bd:serviceParam wikibase:language "en". }
}
ORDER BY ?propertyLabel

SELECT ?language ?count WHERE {
  {
    SELECT ?language (COUNT(?article) AS ?count) WHERE {
      ?article wdt:P31 wd:Q11424.  # instance of film
      ?article schema:about ?item.
      ?article schema:isPartOf ?wiki.
      ?wiki schema:name ?language.
    }
    GROUP BY ?language
    ORDER BY DESC(?count)
    LIMIT 10
  }
}

PREFIX wikibase: <http://wikiba.se/ontology#>
PREFIX mwapi: <http://wikiba.se/ontology#>
PREFIX schema: <http://schema.org/>

SELECT ?topic ?topicLabel WHERE {
  SERVICE wikibase:mwapi {
    wd:Q213690 mwapi:api "query";
               mwapi:list "backlinks";
               mwapi:bltitle "University of Virginia";
               mwapi:bllimit 500;
               mwapi:blnamespace 0 .
    ?page mwapi:page ?page .
  }
  ?topic schema:about ?page .
  ?topic schema:isPartOf <https://en.wikipedia.org/> .
  SERVICE wikibase:label { bd:serviceParam wikibase:language "en". }
}
LIMIT 1000

SELECT ?city ?cityLabel ?population WHERE {
  ?city wdt:P31 wd:Q515;          # instance of city
        wdt:P17 wd:Q183;          # country Germany
        wdt:P1082 ?population.    # population
  FILTER(?population > 50000)
  SERVICE wikibase:label { bd:serviceParam wikibase:language "en". }
}
ORDER BY DESC(?population)

PREFIX wd: <http://www.wikidata.org/entity/>
PREFIX wdt: <http://www.wikidata.org/prop/direct/>
PREFIX p: <http://www.wikidata.org/prop/>
PREFIX ps: <http://www.wikidata.org/prop/statement/>
PREFIX pq: <http://www.wikidata.org/prop/qualifier/>

SELECT ?country ?countryLabel ?isoCode ?flag ?fertilityRate WHERE {
  ?country wdt:P31 wd:Q3624078. # instance of sovereign state
  OPTIONAL { ?country wdt:P298 ?isoCode. } # ISO 3166-1 alpha-3 code
  OPTIONAL { ?country wdt:P41 ?flag. } # flag image
  OPTIONAL { 
    ?country p:P2213 ?fertilityStatement. # fertility rate
    ?fertilityStatement ps:P2213 ?fertilityRate.
    # Optionally filter for most recent year
    OPTIONAL { ?fertilityStatement pq:P585 ?year. }
    FILTER NOT EXISTS { ?fertilityStatement pq:P585 ?year. FILTER (?year < "2010"^^xsd:dateTime) }
  }
  SERVICE wikibase:label { bd:serviceParam wikibase:language "en". }
}

SELECT ?type (COUNT(?work) AS ?count) WHERE {
  ?work wdt:P31 ?type .
  ?type wdt:P279* wd:Q7725634 .
}
GROUP BY ?type
ORDER BY DESC(?count)
